import{chromium}from'playwright-core';const b=await chromium.connectOverCDP('http://127.0.0.1:9224');try{const p=b.contexts().flatMap(c=>c.pages()).find(x=>x.url()==='http://127.0.0.1:30000/game');if(!p)throw Error('missing page');const results=await p.evaluate(()=>{if(!game.ready||game.world?.id!=='cabin-in-the-ashen-veil'||!game.user.isGM||game.users.activeGM.id!==game.user.id)throw Error('GM check');return [['CAVHU04Scene0001','CAVHU04HOPECHST1'],['CAVHU08Scene0001','CAVBE5639AEC2179'],['CAVEXT05Scene001','CAVEXT05LANTERN1']].map(([s,r])=>{const reg=game.scenes.get(s)?.regions.get(r);return {scene:s,region:r,behaviorCount:reg?.behaviors?.size,behaviors:Array.from(reg?.behaviors||[]).map(b=>({id:b.id,uuid:b.uuid,name:b.name,type:b.type,disabled:b.disabled,sourceLen:b.system?.source?.length,events:Array.from(b.system?.events??[])}))}})});console.log(JSON.stringify(results))}finally{await b.close()}